from collections import deque

def check_adjacency_rule(input_grid, output_grid):
    n = len(input_grid)
    violated = []

    for r in range(n):
        for c in range(n):
            if input_grid[r][c] != 0:
                # Check all neighbors
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if input_grid[nr][nc] != 0:
                            if output_grid[r][c] != output_grid[nr][nc]:
                                violated.append(((r,c), (nr,nc), output_grid[r][c], output_grid[nr][nc]))

    return violated

